import "node:module";
const FILE_CLEANUP_REGISTRY = Symbol.for('rstest.file.cleanup.registry');
const getFileCleanupRegistry = ()=>{
    const globalObject = globalThis;
    let registry = globalObject[FILE_CLEANUP_REGISTRY];
    if (!registry) {
        registry = new Set();
        globalObject[FILE_CLEANUP_REGISTRY] = registry;
    }
    return registry;
};
const registerFileCleanup = (cleanup)=>{
    const registry = getFileCleanupRegistry();
    registry.add(cleanup);
    return ()=>registry.delete(cleanup);
};
const takeFileCleanups = ()=>{
    const registry = getFileCleanupRegistry();
    const cleanups = [
        ...registry
    ];
    registry.clear();
    return cleanups;
};
const createFileCleanupTimeoutResult = ({ message, projectName, result, testPath })=>{
    const error = new Error(message);
    return {
        ...result ?? {
            name: '',
            project: projectName,
            results: [],
            testId: `file:${testPath}`,
            testPath
        },
        status: 'fail',
        errors: [
            ...result?.errors ?? [],
            {
                fullStack: true,
                message: error.message,
                name: error.name,
                stack: error.stack
            }
        ]
    };
};
export { createFileCleanupTimeoutResult, registerFileCleanup, takeFileCleanups };
